define interface HasId
  id: int;
end
define class Candidate as
  pub val int id = 11;
  pub val string extra = "x";
end
fnc take(structural HasId x): int { return x.id; }
pub fnc main(): int { return take(new Candidate()); }

define interface Echo
 fnc echo<T>(T x) => T;
end
define class Candidate as
 pub echo<U>(U x): U { return x; }
end
fnc take(structural Echo x): int { return x.echo(7); }

define interface HasId
 id: int;
end
fnc test(record{ id: int } x): int {
 match x over
  on structural HasId v -> { return v.id; }
  on _ -> { return 0; }
 end
}

